#include "json.hpp"
#include <iostream>
#include <fstream>
#include <filesystem>
#include <stdexcept>
using namespace hyperion;
void require(bool v,const char* message){if(!v)throw std::runtime_error(message);}
int main(){try{
 std::ifstream fixtureFile(HYPERION_FIXTURE_PATH);nlohmann::json fixtures;fixtureFile>>fixtures;
 State browserState;std::string browserError;require(loadState(browserState,(std::filesystem::path(HYPERION_FIXTURE_PATH).parent_path()/"browser-v3-save.json").string(),browserError),"Unmodified HTML version-3 save imports");require(browserState.seed=="MERIDIAN-0001"&&browserState.selectedPlanet==2&&browserState.resources[0]==60&&browserState.log.size()==2,"Browser save fields restored");
 auto near=[](double a,double b){return std::abs(a-b)<1.e-8;};
 for(auto& f:fixtures){Universe original(f.at("seed").get<std::string>(),1);require(original.seed()==f.at("hash").get<uint32_t>(),"Original UTF-16 seed hashing");
  for(auto& star:f.at("stars")){auto a=original.star(star.at("id"));require(a.name==star.at("name")&&a.seed==star.at("seed")&&a.numPlanets==star.at("numPlanets")&&near(a.pos.x,star.at("x"))&&near(a.pos.y,star.at("y")),"Original star-generation parity");}
  for(const char* collection:{"planets","remote"})for(auto& p:f.at(collection)){auto a=original.planet(p.at("starId"),p.at("index"));require(a.name==p.at("name")&&a.seed==p.at("seed")&&a.type==p.at("type")&&a.temp==p.at("temp")&&near(a.water,p.at("water"))&&near(a.life,p.at("life"))&&a.formation==p.at("formation"),"Original planet-generation parity");}
  auto p=original.planet("HOME",2);require(near(original.elevation(p,-431,278),f["elev"][0])&&near(original.elevation(p,127.3,-72.8),f["elev"][1]),"Original terrain parity");
  require(near(original.floorDepth(p,-600),f["floor"][0])&&near(original.floorDepth(p,421.7),f["floor"][1]),"Original bathymetry parity");
  auto surf=original.surfaceObjects(p,-3,5),ocean=original.oceanObjects(p,-2);require(surf.size()==f["surface"].size()&&ocean.size()==f["ocean"].size(),"Original contact counts");
  for(size_t i=0;i<surf.size();i++)require(surf[i].id==f["surface"][i]["id"]&&surf[i].name==f["surface"][i]["name"]&&surf[i].kind==f["surface"][i]["kind"]&&near(surf[i].pos.x,f["surface"][i]["x"]),"Original surface-contact parity");
  for(size_t i=0;i<ocean.size();i++)require(ocean[i].id==f["ocean"][i]["id"]&&ocean[i].name==f["ocean"][i]["name"]&&ocean[i].kind==f["ocean"][i]["kind"]&&near(ocean[i].depth,f["ocean"][i]["depth"]),"Original ocean-contact parity");
 }
 Universe u("MERIDIAN-0001"),same("MERIDIAN-0001"),other("OTHER");require(u.star("HOME").name=="MERIDIAN","Home system");require(u.planets("HOME").size()==6,"Six home planets");auto p=u.planet("HOME",2);require(p.name=="NACRE"&&p.type=="ocean"&&p.water==.82&&p.temp==289,"Nacre profile");
 for(int x=-20;x<=20;x++)for(int y=-8;y<=8;y++){auto a=u.cell(x,y),b=same.cell(x,y);require(a.size()==b.size(),"Repeatable sectors");for(size_t i=0;i<a.size();i++){require(a[i].id==b[i].id&&a[i].pos.x==b[i].pos.x&&a[i].name==b[i].name,"Repeatable stars");require(u.star(a[i].id).id==a[i].id,"Star lookup");}}
 require(u.hash(-32,69)!=other.hash(-32,69),"Seeds make different universes");require(u.noise(-4.2,8.1)==same.noise(-4.2,8.1),"Repeatable noise");
 for(int x=-1000;x<=1000;x+=17){double e=u.elevation(p,x,x*.7);require(e>=0&&e<=1,"Height bounds");double d=u.floorDepth(p,x);require(d>=620&&d<=p.oceanMax,"Floor bounds");}
 Game g;require(!g.dive(),"Dive requires surface");g.system("HOME");g.s.selectedPlanet=2;require(g.orbitScan(),"Initial orbital scan");int science=g.s.resources[3];require(!g.orbitScan()&&g.s.resources[3]==science,"No duplicate orbital rewards");require(g.descend(),"Planetfall");V2 start=g.s.surface;g.moveTurn({1,0});require(g.s.surface.x>start.x,"Surface movement commits a turn");g.s.waypoint={g.s.surface.x+20,g.s.surface.y};g.moveTurn({},true);require(std::abs(g.s.surface.x-g.s.waypoint.x)<3,"Surface waypoint advances on an explicit turn");
 Contact item;auto objs=u.surfaceObjects(p,0,0);require(!objs.empty(),"Surface contacts");item=objs.front();require(g.catalogue(item),"Catalogue discovery");auto gains=g.s.resources;require(!g.catalogue(item)&&g.s.resources==gains,"No duplicate discovery rewards");
 require(g.dive(),"Ocean deployment");double d=g.s.depth;g.moveTurn({0,1});require(g.s.depth>d,"Depth step commits a turn");g.s.oceanTargetX=g.s.oceanX+10;g.s.targetDepth=g.s.depth+100;g.moveTurn({},true);require(std::abs(g.s.oceanTargetX-g.s.oceanX)<2&&std::abs(g.s.targetDepth-g.s.depth)<13,"Ocean waypoint advances on an explicit turn");
 g.s.battery=0;require(g.scan()==0,"Low battery blocks scan");double battery=g.s.battery;g.simulate(.1);require(g.s.battery==battery,"No passive recharge outside cockpit");g.endTurn();require(g.s.battery>battery,"Committed turns recharge the battery");
 auto contact=u.oceanObjects(p,0,g.s.oceanAtY).front();g.s.oceanX=contact.pos.x;g.s.depth=contact.depth;g.s.oceanTargetX=g.s.oceanX;g.s.targetDepth=g.s.depth;g.s.battery=100;auto sonarCargo=g.shipStock();require(g.scan()>0,"Sonar reveals reachable contacts");require(!g.s.scanned.count(contact.id)&&g.shipStock()==sonarCargo,"Sonar leaves cataloguing, specimens and minerals for explicit field orders");require(g.s.battery==92,"Sonar spends twelve energy and one turn recovers four");
 g.s.mode=Mode::Ocean;g.s.hull=.001;g.s.depth=1005;g.endTurn();require(g.s.mode==Mode::Surface&&g.s.hull==18,"Pressure emergency surfaces the vessel");
 g.s.resources={10000,10000,10000,10000};auto before=g.s.resources;require(g.purchase(2)&&g.maxDepth()==2700,"Pressure shell upgrade");require(g.s.resources[0]<before[0],"Upgrade spends resources");for(int i=0;i<10;i++)g.purchase(2);require(g.s.upgrades[2]==5&&!g.purchase(2),"Upgrade cap enforced");
 g.system("HOME");g.s.selectedPlanet=4;require(!g.descend(),"Gas giant blocks landing");g.s.selectedPlanet=2;g.launch();g.galaxy();Star destination;double closest=1e9;for(int x=-2;x<=2;x++)for(int y=-2;y<=2;y++)for(auto& s:u.cell(x,y)){double d=distance(s.pos,{0,0});if(s.id!="HOME"&&d<closest){closest=d;destination=s;}}
 g.s.fuel=0;require(!g.travel(destination.id),"Fuel blocks transit");g.refuel();double fuel=g.s.fuel;require(g.travel(destination.id)&&g.s.fuel<fuel&&g.s.visitedStars.count(destination.id),"FTL transit and atlas");
 Game fresh;std::string error;auto file=(std::filesystem::temp_directory_path()/"hyperion-roundtrip-test.json").string();require(saveState(g.s,file,error),"Save writes");require(loadState(fresh.s,file,error),"Save loads");require(fresh.s.seed==g.s.seed&&fresh.s.scanned==g.s.scanned&&fresh.s.discovered.size()==g.s.discovered.size()&&fresh.s.resources==g.s.resources&&fresh.s.upgrades==g.s.upgrades,"Complete save roundtrip");
 {std::ofstream out(file);out<<"{\"version\":3,\"resources\":{},\"currentStar\":\"HOME\",\"seed\":\"x\",\"galaxy\":{\"x\":1e300}}";}State stable=fresh.s;require(!loadState(fresh.s,file,error)&&fresh.s.seed==stable.seed&&fresh.s.resources==stable.resources,"Malformed import is transactional");std::filesystem::remove(file);
 Game endurance;endurance.system("HOME");endurance.s.selectedPlanet=2;endurance.descend();endurance.dive();double idleHours=endurance.s.hours;for(int i=0;i<60000;i++)endurance.simulate(1./60,{1,1});require(endurance.s.hours==idleHours,"1000 idle seconds do not consume expedition turns");for(int i=0;i<128;i++){endurance.moveTurn({std::sin(i*.2),std::cos(i*.2)});if(endurance.s.mode==Mode::Surface)endurance.dive();}require(std::isfinite(endurance.s.depth)&&endurance.s.battery>=0&&endurance.s.hull>0,"Long exploration remains bounded");
 std::cout<<"PASS: exact prototype fixtures (4 seeds / Unicode), deterministic universe, terrain, exploration, scans, economy, navigation, pressure safety, save roundtrip, malformed imports, 1,000 idle seconds and 128 expedition turns\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
